python3 - <<'EOF'
from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid
    try:
        ServerSentEvent(event="hello", id="123")
        print("Success: valid event/id passed")
    except ValidationError as e:
        print(f"Failed: valid event/id raised ValidationError: {e}")

    # Test invalid event (newline)
    try:
        ServerSentEvent(event="line1\nline2")
        print("Failed: event with newline should have raised ValidationError")
    except ValidationError as e:
        print("Success: event with newline raised ValidationError")

    # Test invalid event (carriage return)
    try:
        ServerSentEvent(event="line1\rline2")
        print("Failed: event with carriage return should have raised ValidationError")
    except ValidationError as e:
        print("Success: event with carriage return raised ValidationError")

    # Test invalid id (newline)
    try:
        ServerSentEvent(id="line1\nline2")
        print("Failed: id with newline should have raised ValidationError")
    except ValidationError as e:
        print("Success: id with newline raised ValidationError")

    # Test invalid id (carriage return)
    try:
        ServerSentEvent(id="line1\rline2")
        print("Failed: id with carriage return should have raised ValidationError")
    except ValidationError as e:
        print("Success: id with carriage return raised ValidationError")

    # Test invalid id (null character)
    try:
        ServerSentEvent(id="id\0withnull")
        print("Failed: id with null should have raised ValidationError")
    except ValidationError as e:
        print("Success: id with null raised ValidationError")

test_sse_validation()
EOF
